    image: "/products/axa-pdp/X000010086/black/1.jpg",
    images: ["/products/axa-pdp/X000010086/black/1.jpg", "/products/axa-pdp/X000010086/black/2.jpg", "/products/axa-pdp/X000010086/black/3.jpg", "/products/axa-pdp/X000010086/black/4.jpg", "/products/axa-pdp/X000010086/black/5.jpg", "/products/axa-pdp/X000010086/black/6.jpg", "/products/axa-pdp/X000010086/black/7.jpg"],
